# RAG를 도구로 붙이기: search_docs → 혼합 검색 상위 3개 조각
def rag_search(query, k=3):
    return {"results": [{"source": r["title"], "text": r["text"], "score": r["score"]} for r in retrieve(query, k)],
            "note": "이 내용으로만 답하고, 없으면 모른다고 말할 것"}
TOOL_FUNCS["search_docs"] = rag_search

RAG_QS = ["토요일에도 진료해요?", "주차비는 얼마예요?", "MRI 촬영도 할 수 있어요?"]     # 마지막은 문서에 없는 내용
rows = []
for p in AVAILABLE:
    for q in RAG_QS:
        r = run_agent(p, q)
        rows.append(dict(LLM=p, 질문=q, 도구=" → ".join(r["tools"]) or "(없음)", 대답=r["text"][:70]))
display(pd.DataFrame(rows))
